<?php
if(!isset($db)){http_response_code(404);exit;}
function costingView($admin){if(!$admin){echo '<p>Access denied.</p>';return;}
echo '<div class="onb-dash"><div class="dash-hero"><h1>Trip profitability planner</h1><p>CAD estimates including group leaders, discounts and commissions.</p></div>';
$fields=['people'=>'Paying travellers','leaders'=>'Group leaders','selling'=>'Selling price per traveller','flight'=>'Flight per person','hotel'=>'Total hotel expense','food'=>'Food per person per day','days'=>'Trip days','activity'=>'Activities per person','transport'=>'Shared transport','other'=>'Other shared expenses','commission'=>'Agent commission per referred traveller','referred'=>'Referred paying travellers','discount'=>'Discount per paying traveller','reward'=>'Reward / contingency expense'];
$defaults=[6,1,3500,1300,3000,40,10,200,1000,500,100,0,0,0];$v=[];foreach(array_keys($fields) as $i=>$k)$v[$k]=$defaults[$i];
if(isset($_GET['calculate'])){foreach($fields as $k=>$label){$raw=(string)($_GET[$k]??'');if(!preg_match('/^\d+(\.\d{1,2})?$/D',$raw)||(float)$raw>1000000){echo '<p>Invalid input.</p>';return;}$v[$k]=(float)$raw;}foreach(['people','leaders','days','referred'] as $k)if(floor($v[$k])!==$v[$k]||$v[$k]>1000){echo '<p>Enter valid whole counts.</p>';return;}if(!$v['people']||!$v['days']||$v['referred']>$v['people']||$v['discount']>$v['selling']){echo '<p>Check traveller counts and discount.</p>';return;}}
echo '<form method="get"><input type="hidden" name="page" value="costing"><input type="hidden" name="calculate" value="1">';foreach($fields as $k=>$label)echo '<label>'.h($label).'<input type="number" min="0" step="'.(in_array($k,['people','leaders','days','referred'])?'1':'0.01').'" name="'.h($k).'" value="'.h($v[$k]).'" required></label>';echo '<button>Calculate profitability</button></form>';
$unit=$v['flight']+$v['food']*$v['days']+$v['activity'];$fixed=$v['hotel']+$v['transport']+$v['other']+$v['reward']+$v['leaders']*$unit;$rev=$v['people']*($v['selling']-$v['discount']);$cost=$fixed+$v['people']*$unit+$v['referred']*$v['commission'];$profit=$rev-$cost;$contribution=$v['selling']-$v['discount']-$unit-$v['commission']*$v['referred']/$v['people'];
echo '<div class="metrics">';foreach(['Net sales'=>$rev,'Total estimated cost'=>$cost,'Estimated profit'=>$profit,'Break-even selling price per person'=>$cost/$v['people']+$v['discount']] as $label=>$amount)echo '<article><span>'.h($label).'</span><strong>CAD '.number_format($amount,2).'</strong></article>';echo '</div><p>Break-even paying travellers: '.($contribution>0?max(1,ceil($fixed/$contribution)):'Not achievable at this price').'</p><p>Margin: '.($rev>0?number_format(100*$profit/$rev,1).'%':'Not applicable').'</p><small>Scenario only. Shared expenses and referral mix are assumed constant; excludes unentered taxes and costs.</small></div>';}
